INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Treiber-Updates immer notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Problemen oder neuen Funktionen"}, {"text": "Ja", "correct": false, "because": "Stabile Systeme können ohne auskommen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Treiberwahl entscheidend?', 3, '[{"text": "Hardwarekompatibilität", "correct": true, "because": "Muss zur Hardware passen"}, {"text": "Neueste Version", "correct": false, "because": "Nicht immer stabil"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen Treiber für eine GPU effektiv?', 5, '[{"text": "Optimierte Leistung", "correct": true, "because": "Maximale Grafiknutzung"}, {"text": "Regelmäßige Updates", "correct": true, "because": "Fehlerbehebung und Features"}, {"text": "Kleine Dateigröße", "correct": false, "because": "Weniger wichtig"}, {"text": "Universelle Kompatibilität", "correct": false, "because": "Spezifisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Treiber sind hardwareabhängig. b) Updates erhöhen immer die Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Updates können Fehler einführen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Treiberwahl für einen Server?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Kritisch für Funktion"}, {"text": "Stabilität", "correct": false, "because": "Wichtig für Dauerbetrieb"}, {"text": "Gaming-Optimierungen", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ältere Treiber stabiler sind als neue?', 2, '[{"text": "Ja", "correct": true, "because": "Getestet und bewährt"}, {"text": "Nein", "correct": false, "because": "Neue können Fehler beheben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für eine Netzwerkkarte?', 3, '[{"text": "Aktuelle Treiberversion", "correct": true, "because": "Unterstützt neue Protokolle"}, {"text": "Minimale Latenz", "correct": false, "because": "Hardwareabhängig"}, {"text": "Einfache Installation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten regelmäßige Treiber-Updates?', 5, '[{"text": "Fehlerbehebung", "correct": true, "because": "Bugs werden gefixt"}, {"text": "Leistungssteigerung", "correct": true, "because": "Optimierung möglich"}, {"text": "Kleinere Dateien", "correct": false, "because": "Nicht primär"}, {"text": "Einfachere Bedienung", "correct": false, "because": "Nicht treiberrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Treiber müssen zum OS passen. b) Updates sind nur für neue Hardware. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch alte Hardware profitiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Drucker-Treiber?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zum Gerät passen"}, {"text": "Stabile Verbindung", "correct": false, "because": "Wichtig für Druck"}, {"text": "Overclocking-Support", "correct": true, "because": "Irrelevant für Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind generische Treiber immer schlechter?', 2, '[{"text": "Nein", "correct": true, "because": "Können für Basics reichen"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig unbrauchbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen SSD-Treiber wichtig?', 4, '[{"text": "TRIM-Unterstützung", "correct": true, "because": "Verlängert Lebensdauer"}, {"text": "Hohe Kompatibilität", "correct": true, "because": "Muss zum Controller passen"}, {"text": "Grafikoptimierung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Treiber-Updates die Hardware beschädigen können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Software beeinflusst Hardware nicht physisch"}, {"text": "Ja", "correct": false, "because": "Nur bei Fehlinstallation möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für einen Gaming-PC?', 3, '[{"text": "Leistungsoptimierte Treiber", "correct": true, "because": "Maximale FPS"}, {"text": "Minimale Größe", "correct": false, "because": "Weniger wichtig"}, {"text": "Universelle Unterstützung", "correct": false, "because": "Spezifisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Treiber sind OS-spezifisch. b) Updates sind optional.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) OS-Abhängigkeit, b) situativ"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben veraltete Treiber?', 5, '[{"text": "Fehlende Features", "correct": true, "because": "Neue Funktionen fehlen"}, {"text": "Sicherheitslücken", "correct": true, "because": "Keine Patches"}, {"text": "Höhere Stabilität", "correct": false, "because": "Nicht garantiert"}, {"text": "Kleinere Dateien", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Treiber für einen Server unwichtig?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zur Hardware passen"}, {"text": "Stabilität", "correct": false, "because": "Kritisch für Betrieb"}, {"text": "Spieleunterstützung", "correct": true, "because": "Nicht serverrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Treiber regelmäßig aktualisiert werden?', 3, '[{"text": "Nein", "correct": true, "because": "Nur bei Bedarf oder Problemen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein falscher Treiber Schäden verursacht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Funktionsverlust, kein physischer Schaden"}, {"text": "Ja", "correct": false, "because": "Hardware bleibt unversehrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Treiber wähle ich für eine neue Soundkarte?', 4, '[{"text": "Hersteller-Treiber", "correct": true, "because": "Optimale Leistung und Kompatibilität"}, {"text": "Generischer Treiber", "correct": false, "because": "Eingeschränkte Funktionen"}, {"text": "Ältere Version", "correct": false, "because": "Fehlende Updates"}]');
